// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

// 导入OpenZeppelin的安全合约 - 使用英文引号，没有空格
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title SimpleCrowdfunding
 * @dev 一个简单的"全部或无"式众筹合约
 */
contract SimpleCrowdfunding is Ownable, ReentrancyGuard {
    // 众筹项目状态
    enum State {
        Active,
        Successful,
        Failed
    }

    // 众筹项目结构体
    struct Project {
        address payable creator; // 项目发起人
        uint goal;               // 目标金额（单位：wei）
        uint deadline;           // 截止时间（Unix时间戳）
        uint amountRaised;       // 已筹集金额
        State state;             // 当前状态
    }

    // 状态变量
    Project public project;
    
    // 记录每个支持者的捐款金额
    mapping(address => uint) public contributions;

    // 事件：用于前端监听和日志记录
    event ProjectFunded(address backer, uint amount);
    event GoalReached(uint totalAmountRaised);
    event FundsWithdrawnByCreator(uint amount);
    event RefundClaimed(address backer, uint amount);

    /**
     * @dev 构造函数，部署时初始化项目
     * @param _goal 目标金额（单位：wei）
     * @param _duration 众筹持续时间（单位：秒），例如：7天 = 7*24*60*60
     */
    constructor(uint _goal, uint _duration) {
        project = Project({
            creator: payable(msg.sender), // 部署者为发起人
            goal: _goal,
            deadline: block.timestamp + _duration,
            amountRaised: 0,
            state: State.Active
        });
    }

    /**
     * @dev 支持者捐款函数
     */
    function fund() public payable nonReentrant {
        // 1. 检查项目是否仍在进行中
        require(block.timestamp < project.deadline, "Campaign has ended.");
        require(project.state == State.Active, "Campaign is not active.");

        // 2. 检查捐款金额大于0
        require(msg.value > 0, "Contribution must be greater than 0.");

        // 3. 更新状态
        project.amountRaised += msg.value;
        contributions[msg.sender] += msg.value;

        // 4. 检查目标是否达成
        if (project.amountRaised >= project.goal) {
            project.state = State.Successful;
            emit GoalReached(project.amountRaised);
        }

        // 5. 发射捐款事件
        emit ProjectFunded(msg.sender, msg.value);
    }

    /**
     * @dev 项目发起人提取资金（仅在众筹成功时调用）
     */
    function withdrawFunds() public nonReentrant {
        // 1. 检查调用者是否是发起人
        require(msg.sender == project.creator, "Only creator can withdraw.");

        // 2. 检查项目是否成功
        require(project.state == State.Successful, "Campaign must be successful to withdraw.");
        require(block.timestamp > project.deadline, "Campaign must be over.");

        // 3. 检查合约余额
        uint balance = address(this).balance;
        require(balance > 0, "No funds to withdraw.");

        // 4. 转账
        (bool success, ) = project.creator.call{value: balance}("");
        require(success, "Transfer failed.");

        // 5. 发射事件
        emit FundsWithdrawnByCreator(balance);
    }

    /**
     * @dev 支持者退款函数（仅在众筹失败时调用）
     */
    function claimRefund() public nonReentrant {
        // 1. 检查项目是否已失败
        // 注意：我们设定一个规则，只有在截止时间过后且未达目标才算失败
        if (project.state == State.Active && block.timestamp > project.deadline && project.amountRaised < project.goal) {
            project.state = State.Failed;
        }
        require(project.state == State.Failed, "Campaign must be failed to claim refund.");

        // 2. 检查调用者是否有捐款可退
        uint amountToRefund = contributions[msg.sender];
        require(amountToRefund > 0, "No contributions to refund.");

        // 3. 防止重入攻击：先清零，再转账
        contributions[msg.sender] = 0;

        // 4. 转账
        (bool success, ) = msg.sender.call{value: amountToRefund}("");
        require(success, "Refund transfer failed.");

        // 5. 发射事件
        emit RefundClaimed(msg.sender, amountToRefund);
    }

    /**
     * @dev 获取合约当前余额（用于测试和前端显示）
     */
    function getContractBalance() public view returns (uint) {
        return address(this).balance;
    }

    /**
     * @dev 获取项目详情（用于测试和前端显示）
     */
    function getProjectDetails() public view returns (Project memory) {
        return project;
    }
}

